-- =============================================================================
-- 533 — LE CAHIER D'EXERCICES DE 1RE (partie 21)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 533 --niveau 1re --fichiers francais.n9a,francais.n9b,hggsp.n1,hggsp.n2 --suffixe 21 > supabase/contenu/533_exercices_1re_21.sql
--
-- 90 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.n9a            18 exercices · 6 chapitres
--   francais.n9b            18 exercices · 6 chapitres
--   hggsp.n1                27 exercices · 9 chapitres
--   hggsp.n2                27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('d31e3158-38a9-5c99-9128-2e28c40573a4'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Un poète condamné à la corde","competence":"se-reperer-temps","situation":"Tu prépares une fiche sur la « Ballade des pendus ». Place Villon dans le temps, puis relève la forme de son poème.","documents":[{"id":"frise","type":"frise","titre":"Villon, de la naissance à la condamnation","debut":1430,"fin":1470,"pas":5,"evenements":[{"id":"z1","date":1431,"nom":"Naissance"},{"id":"z2","date":1456,"nom":"Vol du collège"},{"id":"z3","date":1462,"nom":"Condamné"}]},{"id":"fiche","type":"fiche","modele":"affiche","entete":"Ballade des pendus","sousTitre":"François Villon","emoji":"📜","lignes":[{"texte":"Autre titre","valeur":"« L’Épitaphe Villon »"},{"texte":"Genre","valeur":"Ballade"},{"texte":"Strophes","valeur":"Trois dizains, plus un envoi"},{"texte":"Vers","valeur":"Décasyllabes"}],"pied":"Poème médiéval, XVe siècle","teinte":"violet"}],"questions":[{"enonce":"Sur la frise, touche l’année où Villon est condamné à être pendu.","aide":"Cherche l’événement le plus tardif de la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la naissance de Villon de sa condamnation à la pendaison ?","aide":"Soustrais les deux dates lues sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Complète la phrase avec la fiche du poème.","aide":"Tout est dans les lignes « Genre » et « Strophes » de la fiche.","type":"trous","segments":["Le poème est une ",0," de trois ",1," de décasyllabes, suivis d’un ",2,"."],"banque":["sonnet","quatrains","ballade","envoi","dizains","refrain"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"Villon est condamné à la pendaison en **1462** ; sa peine sera ensuite commuée en bannissement."},{"cle":{"type":"nombre","valeur":31,"tolerance":0},"affichage":"31 ans","explication":"1462 − 1431 = **31 ans** : Villon a une trentaine d’années quand il échappe de justesse à la corde."},{"cle":{"type":"trous","trous":[["ballade"],["dizains"],["envoi"]]},"affichage":"ballade · dizains · envoi","explication":"Une **ballade** : trois **dizains** de décasyllabes, puis un court **envoi** adressé à un destinataire."}]$ex$::jsonb),
  ('d31e3158-38a9-5c99-9128-2e28c40573a4'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Les corps rongés","competence":"analyser-document","situation":"Les pendus parlent à ceux qui passent sous le gibet. Lis ce qu’ils décrivent d’eux-mêmes et ce qu’ils demandent.","documents":[{"id":"pendus","type":"tableau","titre":"Ce que disent les pendus","colonnes":["Ils parlent de…","Ce qu’ils disent"],"lignes":[["Leurs corps","Rongés par la pluie, noircis par le soleil"],["Leur chair","« plus becquetés d’oiseaux que dés à coudre »"],["Leur demande","?"]],"enteteLignes":true,"source":"François Villon, *Ballade des pendus* (L’Épitaphe Villon), orthographe modernisée"}],"questions":[{"enonce":"Touche la case où les pendus se comparent à un objet de couture.","aide":"Cherche l’objet qu’on enfile au doigt pour coudre.","type":"zone","document":"pendus","multiple":false},{"enonce":"Quel effet cette comparaison avec le dé à coudre produit-elle ?","aide":"Les pendus demandent justement qu’on ne se moque pas d’eux.","type":"choix","options":[{"id":"a","texte":"Une plaisanterie qui invite le lecteur à se moquer"},{"id":"b","texte":"Une image tendre qui adoucit la mort des suppliciés"},{"id":"c","texte":"Une description savante du métier de couturier"},{"id":"d","texte":"Une image concrète et crue des corps abîmés par les oiseaux"}],"multiple":false},{"enonce":"Complète la case « ? » : ce que demandent les pendus aux vivants.","aide":"Les pendus ne veulent pas qu’on rie d’eux, mais qu’on pense à leur salut.","type":"trous","segments":["Ils demandent la ",0," et l’absence de ",1,"."],"banque":["prière","justice","admiration","vengeance","moquerie"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La formule « plus becquetés d’oiseaux que **dés à coudre** » dit que les corps sont criblés de coups de bec, comme un dé est criblé de petits creux."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’image est **concrète et crue** : elle fait voir les corps picorés. Le macabre n’est pas là pour faire rire, mais pour toucher."},{"cle":{"type":"trous","trous":[["priere"],["moquerie"]]},"affichage":"prière · moquerie","explication":"Les pendus demandent la **prière** et l’absence de **moquerie** : ils ne réclament pas d’être admirés."}]$ex$::jsonb),
  ('d31e3158-38a9-5c99-9128-2e28c40573a4'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Coupables, mais frères","competence":"argumenter","situation":"Hugo et Nora ne lisent pas le poème de la même façon. Appuie-toi sur le dialogue et sur deux vers pour savoir qui a raison.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Hugo","emoji":"👦","cote":"gauche"},{"nom":"Nora","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Hugo","texte":"Les pendus se plaignent : ils disent qu’on les a condamnés à tort."},{"qui":"Nora","texte":"Pas du tout. Ils ne nient jamais leur faute : ils demandent la pitié des vivants."},{"qui":"Hugo","texte":"Alors pourquoi les appeler « frères » ?"},{"qui":"Nora","texte":"Parce que tous les hommes sont pécheurs : les vivants ressemblent aux pendus."}]},{"id":"vers","type":"texte","genre":"poeme","titre":"Deux vers de la ballade","blocs":["Ne soyez donc de notre confrérie ;","Mais priez Dieu que tous nous veuille absoudre !"],"source":"François Villon, *Ballade des pendus* (L’Épitaphe Villon), orthographe modernisée"}],"questions":[{"enonce":"Touche le mot qui dit ce que Nora pense que les pendus demandent aux vivants.","aide":"Nora le dit juste après « Pas du tout ».","type":"zone","document":"deb","multiple":false},{"enonce":"Touche le verbe qui dit ce que les pendus espèrent de Dieu.","aide":"Ils veulent que Dieu leur pardonne.","type":"zone","document":"vers","multiple":false},{"enonce":"Quelle lecture le poème permet-il de défendre ?","aide":"Que signifie le mot « absoudre » dans le second vers ?","type":"choix","options":[{"id":"a","texte":"Un éloge de la gloire des brigands de Paris"},{"id":"b","texte":"Un jeu d’esprit sans aucun rapport avec la mort réelle"},{"id":"c","texte":"Des condamnés qui reconnaissent leur faute et demandent le salut"},{"id":"d","texte":"Des innocents qui accusent la justice des hommes d’injustice"}],"multiple":false},{"enonce":"Relie chaque procédé du poème à son effet.","aide":"Pense à ce que chaque élément répète, adresse ou 