   $ex$[{"cle":{"type":"zone","ids":["m25"]},"explication":"Pour Nora, les pendus demandent la **pitié** : ils s’adressent aux vivants comme à des frères, sans se déclarer innocents."},{"cle":{"type":"zone","ids":["m13"]},"explication":"**Absoudre**, c’est pardonner une faute : on n’espère pas l’absolution quand on se croit innocent."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le verbe **absoudre** montre des pécheurs qui se savent coupables : la lecture de Nora est la bonne."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Le **refrain** rend la prière obsédante, **« frères humains »** rappelle la fraternité, l’**envoi** adresse la supplication au Prince Jésus."}]$ex$::jsonb),
  ('d903acde-3203-5efd-88ae-790d630258b7'::uuid, 1, 1, 5, 20, 3,
