   $ex${"titre":"Du crime dans le train à la machine folle","competence":"analyser-document","situation":"Suis l’engrenage du roman, du premier meurtre jusqu’au dernier voyage de la Lison.","documents":[{"id":"fil","type":"chaine","titre":"L’engrenage du roman","disposition":"colonne","noeuds":[{"id":"z1","texte":"Roubaud tue Grandmorin dans un train"},{"id":"z2","texte":"Jacques Lantier aperçoit le crime en une seconde"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Jacques finit par tuer Séverine"},{"id":"z5","texte":"Cabuche, innocent, est condamné"},{"id":"z6","texte":"Jacques et Pecqueux tombent de la machine lancée"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"},{"de":"z5","a":"z6"}]}],"questions":[{"enonce":"Quelle étape manque dans la chaîne (la case « ? ») ?","aide":"Entre le témoin du crime et le meurtre de Séverine, Jacques se rapproche d’elle.","type":"choix","options":[{"id":"a","texte":"Jacques devient l’amant de Séverine"},{"id":"b","texte":"Séverine s’enfuit avec Cabuche"},{"id":"c","texte":"Jacques quitte la Compagnie des chemins de fer"},{"id":"d","texte":"Jacques dénonce Roubaud à la justice"}],"multiple":false},{"enonce":"Touche l’étape où un innocent paie pour les autres.","aide":"Qui est condamné sans avoir rien fait ?","type":"zone","document":"fil","multiple":false},{"enonce":"Complète la dernière image du roman.","aide":"Qui monte dans ce train au moment où la guerre commence ?","type":"trous","segments":["Le train continue ",0," conducteur, plein de ",1," ivres qui partent pour la guerre de 1870."],"banque":["voyageurs","avec","soldats","mineurs","sans"]},{"enonce":"Relie chaque personnage à son rôle.","aide":"Chacun gravite autour de la voie ferrée ou de la justice.","type":"association","gauche":[{"id":"g0","texte":"Pecqueux"},{"id":"g1","texte":"Misard"},{"id":"g2","texte":"Camy-Lamotte"},{"id":"g3","texte":"Flore"}],"droite":[{"id":"d0","texte":"Le chauffeur de Jacques"},{"id":"d1","texte":"