   $ex${"titre":"Un aveu qui ne sauve rien","competence":"argumenter","situation":"Compare le dénouement de *La Comtesse de Tende* à celui de *La Princesse de Clèves*, puis lis la lettre d’aveu écrite à la manière de l’autrice.","documents":[{"id":"comp","type":"tableau","titre":"Deux traitements du même dilemme","colonnes":["Dans La Princesse de Clèves","Dans La Comtesse de Tende"],"lignes":[["L’aveu précède la faute","La passion est consommée"],["L’héroïne renonce","?"]],"enteteLignes":false},{"id":"lettre","type":"texte","genre":"lettre","titre":"La lettre d’aveu","blocs":["Monsieur, je vous dois un aveu que je n’ose vous faire de vive voix. Je suis coupable, et je n’attends de vous aucune grâce. Faites de moi ce que votre honneur vous commande."],"source":"Lettre écrite pour l’exercice, à la manière de Madame de La Fayette"}],"questions":[{"enonce":"Touche le mot qui nomme ce que la comtesse écrit à son mari.","aide":"C’est un mot du même champ que « confession ».","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche les deux mots qui montrent qu’elle se reconnaît fautive et n’espère rien.","aide":"Un adjectif dit la faute ; un nom dit ce qu’elle renonce à demander.","type":"zone","document":"lettre","multiple":true},{"enonce":"Quel contraste faut-il écrire dans la case « ? » du tableau ?","aide":"Chez Madame de La Fayette, ici, l’aveu ne libère pas.","type":"choix","options":[{"id":"a","texte":"L’enfant naît, et la mort suit"},{"id":"b","texte":"L’héroïne trouve un nouveau mari"},{"id":"c","texte":"La cour pardonne tout aux amants"},{"id":"d","texte":"La princesse se retire au couvent"}],"multiple":false},{"enonce":"Relie chaque caractéristique de la nouvelle à son effet.","aide":"Pense à ce que chaque choix d’écriture ou d’intrigue rend plus sombre.","type":"association","gauche":[{"id":"g0","texte":"Un récit bref et sec"},{"id":"g1","texte":"Un aveu qui ne sauve rien"},{"id":"g2","texte":"Une passion consommée"}],"droite":[{"id":"d0","texte":