   $ex${"titre":"Plusieurs réponses à une même question","competence":"analyser-document","situation":"Lis le résumé de la révolution de Shanghai, puis compare ce que chaque personnage oppose à la condition humaine.","documents":[{"id":"resume","type":"texte","genre":"recit","titre":"Le contexte du roman","blocs":["À Shanghai, en mars 1927, les communistes chinois, alliés du Kuomintang, s’emparent de la ville. Tchang Kaï-chek les fait ensuite massacrer.","Le baron Clappique, mythomane et joueur, est retenu au casino : son oubli coûtera la vie à Kyo."],"source":"Texte écrit pour l’exercice, d’après le résumé du roman"},{"id":"rep","type":"tableau","titre":"Face à la condition humaine","colonnes":["Personnage","Sa réponse"],"lignes":[["Kyo","La révolution"],["Le vieux Gisors","?"],["Ferral","L’érotisme, vécu comme une domination"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit ce que Tchang Kaï-chek fait des communistes après la prise de la ville.","aide":"Le verbe est à l’infinitif, juste après « fait ensuite ».","type":"zone","document":"resume","multiple":false},{"enonce":"Touche le lieu qui retient Clappique au moment décisif.","aide":"C’est un lieu où l’on joue de l’argent.","type":"zone","document":"resume","multiple":false},{"enonce":"Que faut-il écrire dans la case « ? » pour le vieux Gisors ?","aide":"Le cours le présente comme un sinologue fumeur d’opium.","type":"choix","options":[{"id":"a","texte":"L’opium, qui fait oublier le monde"},{"id":"b","texte":"L’action armée dans la ville"},{"id":"c","texte":"La banque et la finance"},{"id":"d","texte":"La peinture et l’art"}],"multiple":false},{"enonce":"Relie chaque personnage à son rôle dans le roman.","aide":"Chaque personnage est défini par son rôle auprès de Kyo ou de la révolution.","type":"association","gauche":[{"id":"g0","texte":"May"},{"id":"g1","texte":"Ferral"},{"id":"g2","texte":"Hemmelrich"},{"id":"g3","texte":"König"}],"droite":[{"id":"d0","texte":"Le Belge pauvre, dont la fa