s exemples du cours.","type":"choix","options":[{"id":"a","texte":"Le roman refuse de poser la question de la condition humaine aux lecteurs"},{"id":"b","texte":"Le roman montre que la fraternité est impossible entre les révolutionnaires"},{"id":"c","texte":"Plusieurs personnages répondent chacun à leur manière à la condition humaine"},{"id":"d","texte":"Le roman ne propose qu’une seule réponse à la condition humaine : la révolution"}],"multiple":false}]}$ex$::jsonb,
