   $ex${"titre":"Mirabel vote toujours, mais est-ce démocratique ?","competence":"analyser-document","situation":"Une journaliste enquête sur Mirabel, un pays imaginé où l’on vote régulièrement. Elle réunit un extrait de reportage et les résultats du parti au pouvoir.","documents":[{"id":"reportage","type":"texte","genre":"article","titre":"Reportage à Mirabel","source":"Texte écrit pour l’exercice.","blocs":["À Mirabel, une élection présidentielle a lieu tous les quatre ans, avec plusieurs candidats sur les bulletins.","Mais depuis 2012, le même parti a gagné toutes les élections, parfois avec plus de 80 % des voix.","Deux chaînes de télévision critiques ont été fermées et le chef de l’opposition est en prison depuis 2019.","Les juges de la Cour constitutionnelle sont désormais nommés par le président."]},{"id":"scores","type":"graphique","forme":"barres","titre":"Part des voix du parti au pouvoir","source":"Chiffres imaginés pour l’exercice.","categories":["2012","2016","2020","2024"],"series":[{"nom":"Voix","valeurs":[52,61,74,83],"teinte":"violet"}],"axeY":{"titre":"Part des voix","unite":"%","min":0,"max":100,"pas":20},"valeurs":false}],"questions":[{"enonce":"Touche le mot qui montre une atteinte à la presse libre.","aide":"Cherche ce qui est arrivé aux chaînes de télévision critiques.","type":"zone","document":"reportage","multiple":false},{"enonce":"Touche le mot qui montre que la justice dépend du pouvoir.","aide":"Regarde qui décide de la composition de la Cour constitutionnelle.","type":"zone","document":"reportage","multiple":false},{"enonce":"De combien de points la part des voix du parti au pouvoir a-t-elle augmenté entre 2012 et 2024 ?","aide":"Lis la première et la dernière barre, puis soustrais.","type":"nombre","unite":"points"},{"enonce":"Comment qualifier le régime de Mirabel ?","aide":"Il garde les élections, mais affaiblit la presse, la justice et l’opposition.","type":"choix","options":[{"id":"a","texte":"Une démocratie directe"},{"id":"b","texte":"Une dictature sans aucune élection"},{"id":"c","texte":"Une démocratie libérale"},{"id":"d","texte":"Un régime illibéral"}],"multiple":false},{"enonce":"Pourquoi la tenue d’élections ne suffit-elle pas à prouver que Mirabel est une démocratie ?","aide":"Souviens-toi du critère décisif : pouvoir perdre le pouvoir.","type":"choix","options":[{"id":"a","texte":"Le nombre de candidats inscrits sur les bulletins est trop faible"},{"id":"b","texte":"Le scrutin n’a lieu que tous les quatre ans, ce qui est trop long"},{"id":"c","texte":"L’opposition n’a plus de chance réelle de gagner et de prendre le pouvoir"},{"id":"d","texte":"Le parti au pouvoir a reçu plus de la moitié des voix"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m42"]},"explication":"Les chaînes ont été **fermées** : sans presse libre, l’opposition ne peut plus se faire entendre."},{"cle":{"type":"zone","ids":["m62"]},"explication":"Les juges sont **nommés** par le président : la justice n’est plus indépendante, elle ne peut plus contrôler le pouvoir."},{"cle":{"type":"nombre","valeur":31,"tolerance":0},"affichage":"31 points","explication":"83 − 52 = **31 points** de plus : le parti gagne toujours, et de plus en plus largement."},{"cle":{"type":"choix","ids":["d"]},"explication":"Mirabel est un **régime illibéral** : les élections existent, mais les contre-pouvoirs sont affaiblis."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le critère décisif est la possibilité réelle de **perdre le pouvoir** et de le céder. À Mirabel, l’alternance n’est plus possible."}]$ex$::jsonb),
