  ('aebabe0c-6a7d-5b05-93fa-a0661d8e1ab8'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Combien d’Athéniens votent vraiment ?","competence":"lire-graphique","situation":"Zoé lit le graphique de la population de l’Attique au Ve siècle avant notre ère. Elle veut mesurer la part des habitants qui décident vraiment.","documents":[{"id":"pop","type":"graphique","forme":"barres","titre":"Habitants et citoyens en Attique","source":"Chiffres arrondis, d’après le cours.","categories":["Habitants de l’Attique","Citoyens athéniens"],"series":[{"nom":"Personnes","valeurs":[300000,40000],"teinte":"violet"}],"axeY":{"titre":"Nombre de personnes","unite":"","min":0,"max":300000,"pas":100000},"valeurs":false}],"questions":[{"enonce":"Touche la barre qui représente les citoyens.","aide":"Les citoyens sont bien moins nombreux que l’ensemble des habitants.","type":"zone","document":"pop","multiple":false},{"enonce":"Combien d’habitants de l’Attique ne sont pas citoyens ?","aide":"Soustrais le nombre de citoyens au nombre d’habitants.","type":"nombre","unite":"personnes"},{"enonce":"Quelle part des habitants les citoyens représentent-ils, arrondie à l’unité ?","aide":"Divise 40 000 par 300 000, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Range chaque personne : citoyen ou exclu de la citoyenneté ?","aide":"Rappelle-toi la loi de Périclès de 451 : père ET mère athéniens.","type":"categories","categories":[{"id":"c0","texte":"Citoyen"},{"id":"c1","texte":"Exclu de la citoyenneté"}],"items":[{"id":"i0","texte":"Un métèque installé à Athènes depuis trois générations"},{"id":"i1","texte":"Un homme, fils d’un Athénien et d’une étrangère, sous la loi de 451"},{"id":"i2","texte":"Un esclave travaillant dans un atelier"},{"id":"i3","texte":"Un homme adulte, né d’un père et d’une mère athéniens"},{"id":"i4","texte":"Une femme née de parents athéniens"}]}]}$ex$::jsonb,
