  ('aebabe0c-6a7d-5b05-93fa-a0661d8e1ab8'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le cordonnier, le métèque et le stratège","competence":"analyser-document","situation":"Un matin de session, un récit imaginé met côte à côte trois Athéniens très différents. Un tableau résume ce que chacun peut ou non faire.","documents":[{"id":"scene","type":"texte","genre":"recit","titre":"Matin sur la Pnyx","source":"Récit écrit pour l’exercice.","blocs":["Nikias, cordonnier, a été tiré au sort pour siéger à la Boulê. Il est payé pour cela, et peut donc laisser son échoppe quelques jours.","Près de lui, Xénon, un étranger libre installé à Athènes depuis trois générations, paie l’impôt et partira à la guerre comme les autres. Pourtant, il ne peut pas lever la main pour voter.","Un stratège, élu pour sa compétence militaire, prend la parole le premier. Mais tout citoyen, même le plus modeste, a le droit de lui répondre."]},{"id":"droits","type":"tableau","titre":"Qui peut quoi à Athènes ?","source":"D’après le cours.","colonnes":["Droit","Citoyen","Métèque"],"lignes":[["Voter à l’Ecclésia","Oui","Non"],["Siéger à la Boulê","Oui","Non"],["Servir dans l’armée","Oui","Oui"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre que la participation est indemnisée.","aide":"Cherche ce qui permet à un artisan de laisser son échoppe.","type":"zone","document":"scene","multiple":false},{"enonce":"Touche le mot qui désigne le groupe de Xénon, exclu du vote.","aide":"On parle d’un habitant libre mais non athénien.","type":"zone","document":"scene","multiple":false},{"enonce":"Combien de ces trois activités un métèque peut-il exercer ?","aide":"Compte les « Oui » dans la colonne « Métèque ».","type":"nombre"},{"enonce":"Pourquoi Xénon, qui sert à l’armée, ne vote-t-il pas ?","aide":"Pense à la loi de Périclès de 451.","type":"choix","options":[{"id":"a","texte":"Les stratèges sont élus et non tirés au sort"},{"id":"b","texte":"Il a refusé de participer au tirage au sort de la Boulê"},{"id":"c","texte":"Il est trop pauvre pour être indemnisé de son temps"},{"id":"d","texte":"La citoyenneté suppose d’être né de père et de mère athéniens"}],"multiple":false},{"enonce":"Complète le bilan.","aide":"Les citoyens décident eux-mêmes, mais tous les habitants ne le sont pas.","type":"trous","segments":["Athènes est une démocratie ",0,", mais ",1," : une minorité d’habitants seulement y est citoyenne."],"banque":["universelle","représentative","limitée","directe"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m14"]},"explication":"Nikias est **payé** : c’est la misthophorie, qui permet aux plus pauvres de siéger."},{"cle":{"type":"zone","ids":["m30"]},"explication":"Xénon est un **étranger** libre, c’est-à-dire un métèque : il paie l’impôt et sert à l’armée sans voter."},{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1","explication":"Le métèque ne peut ni voter ni siéger à la Boulê : il peut seulement **servir dans l’armée**, soit **1** activité sur 3."},{"cle":{"type":"choix","ids":["d"]},"explication":"La citoyenneté est réservée à ceux qui sont **nés de père et de mère athéniens** : un métèque, même installé depuis des générations, en est exclu."},{"cle":{"type":"trous","trous":[["directe"],["limitee"]]},"affichage":"directe · limitée","explication":"Athènes est une démocratie **directe** mais **limitée** : participation intense, exclusion massive."}]$ex$::jsonb),
  ('1ff1cc71-c548-5cba-bfb5-b82dfdea55f5'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre dates pour un modèle","competence":"se-reperer-temps","situation":"Karim colle sur son mur une frise des révolutions qui ont installé le gouvernement représentatif. Il veut en retenir quatre dates clés.","documents":[{"id":"frise","type":"frise","titre":"Les révolutions et leurs textes","source":"D’après le cours.","debut":1680,"fin":1810,"pas":10,"evenements":[{"id":"z1","date":1689,"nom":"Bill of Rights"},{"id":"z2","date":1776,"nom":"Indépendance US"},{"id":"z3","date":1787,"nom":"Constitution US"},{"id":"z4","date":1789,"nom":"Droits de l’homme"},{"id":"z5","date":1792,"nom":"République"},{"id":"z6","date":1802,"nom":"Esclavage rétabli"}]}],"questions":[{"enonce":"Touche le texte qui fonde la monarchie parlementaire en Angleterre.","aide":"C’est le plus ancien événement de la frise.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent le Bill of Rights anglais de la Déclaration d’indépendance américaine ?","aide":"Soustrais 1689 à 1776.","type":"nombre","unite":"ans"},{"enonce":"Range ces événements du plus ancien au plus récent.","aide":"Lis la frise de gauche à droite.","type":"ordre","items":[{"id":"a","texte":"Constitution américaine"},{"id":"b","texte":"Déclaration d’indépendance américaine"},{"id":"c","texte":"Bill of Rights anglais"},{"id":"d","texte":"Proclamation de la République en France"}]}]}$ex$::jsonb,
