  ('1ff1cc71-c548-5cba-bfb5-b82dfdea55f5'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Un député de 1789 écrit à ses électeurs","competence":"analyser-texte","situation":"Un député imaginé explique à ses électeurs ce qu’il va faire à Paris. Ses phrases résument l’esprit du gouvernement représentatif.","documents":[{"id":"depute","type":"texte","genre":"lettre","titre":"Lettre d’un député à ses électeurs","source":"Lettre imaginée pour l’exercice, dans l’esprit des débats de 1789.","blocs":["Chers électeurs, vous m’avez envoyé siéger à Paris. Je n’y représente pas seulement notre ville : je parle au nom de la Nation tout entière.","Je voterai selon ma conscience, et vous ne pourrez pas me révoquer avant la fin de mon mandat.","Le peuple ne fait pas lui-même la loi : il choisit ceux qui la feront."]},{"id":"textes","type":"tableau","titre":"Trois textes fondateurs","source":"D’après le cours.","colonnes":["Pays","Texte fondateur","Année"],"lignes":[["Angleterre","Bill of Rights","1689"],["États-Unis","Constitution","1787"],["France","Déclaration des droits de l’homme et du citoyen","1789"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit au nom de qui le député parle.","aide":"Il ne représente pas seulement sa ville.","type":"zone","document":"depute","multiple":false},{"enonce":"Touche le mot qui montre que ses électeurs ne peuvent pas l’écarter en cours de mandat.","aide":"Cherche ce que les électeurs ne pourront pas faire.","type":"zone","document":"depute","multiple":false},{"enonce":"Quel régime ce député décrit-il ?","aide":"Relis la dernière phrase de la lettre.","type":"choix","options":[{"id":"a","texte":"Un régime présidentiel fédéral : chaque État fait sa propre loi"},{"id":"b","texte":"Une monarchie absolue : le roi décide seul de toutes les lois"},{"id":"c","texte":"Une démocratie directe : le peuple vote lui-même chaque loi"},{"id":"d","texte":"Un gouvernement représentatif : le peuple choisit ceux qui feront la loi"}],"multiple":false},{"enonce":"Combien d’années séparent le Bill of Rights anglais de la Constitution américaine ?","aide":"Soustrais 1689 à 1787.","type":"nombre","unite":"ans"},{"enonce":"Associe chaque pays au régime que sa révolution institue.","aide":"Le roi anglais ne peut plus lever l’impôt sans le Parlement.","type":"association","gauche":[{"id":"g0","texte":"Angleterre"},{"id":"g1","texte":"États-Unis"},{"id":"g2","texte":"France en 1792"}],"droite":[{"id":"d0","texte":"Monarchie parlementaire"},{"id":"d1","texte":"République"},{"id":"d2","texte":"Régime présidentiel et fédéral"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m23"]},"explication":"Le député parle au nom de la **Nation** : c’est le mandat représentatif."},{"cle":{"type":"zone","ids":["m37"]},"explication":"Le député n’est pas **révocable** : c’est l’autre trait du mandat représentatif."},{"cle":{"type":"choix","ids":["d"]},"explication":"Comme Sieyès, il distingue la démocratie, où le peuple fait la loi, du **gouvernement représentatif**, où il choisit ceux qui la feront."},{"cle":{"type":"nombre","valeur":98,"tolerance":0},"affichage":"98 ans","explication":"1787 − 1689 = **98 ans**."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"L’Angleterre devient une **monarchie parlementaire**, les États-Unis un régime **présidentiel et fédéral**, la France une **République** en 1792."}]$ex$::jsonb),
  ('1ff1cc71-c548-5cba-bfb5-b82dfdea55f5'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Qui vote vraiment vers 1790 ?","competence":"argumenter","situation":"Une lettre imaginée et une frise permettent de mesurer l’écart entre les principes proclamés et la réalité des droits vers 1790.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’une habitante des États-Unis","source":"Lettre imaginée pour l’exercice.","blocs":["Chère sœur, la grande fête de l’élection a eu lieu hier. Mon mari a pu voter, car il paie assez d’impôt ; notre voisin Samuel, qui travaille sans rien posséder, n’en a pas eu le droit.","Moi, comme toutes les femmes, je suis restée à la maison. Et chez nos cousins de Virginie, des hommes et des femmes travaillent la terre sans être libres du tout."]},{"id":"frise","type":"frise","titre":"Droits proclamés et reculs en France","source":"D’après le cours.","debut":1785,"fin":1805,"pas":5,"evenements":[{"id":"z1","date":1789,"nom":"Droits de l’homme"},{"id":"z2","date":1792,"nom":"Convention élue"},{"id":"z3","date":1802,"nom":"Esclavage rétabli"}]}],"questions":[{"enonce":"Touche le mot qui indique le critère qui permet de voter.","aide":"Le mari vote parce qu’il paie assez de…","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche l’événement qui est un recul par rapport aux principes de 1789.","aide":"Pense au statut de ceux qui ne sont pas libres.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la Déclaration des droits de l’homme du rétablissement de l’esclavage ?","aide":"Soustrais 1789 à 1802.","type":"nombre","unite":"ans"},{"enonce":"Range chaque élément : principe consacré ou limite du moment ?","aide":"Les limites sont ce qui restreint le droit de vote ou la liberté.","type":"categories","categories":[{"id":"c0","texte":"Un principe consacré"},{"id":"c1","texte":"Une limite du moment"}],"items":[{"id":"i0","texte":"L’esclavage maintenu"},{"id":"i1","texte":"Le suffrage censitaire"},{"id":"i2","texte":"La séparation des pouvoirs"},{"id":"i3","texte":"L’exclusion des femmes"},{"id":"i4","texte":"La constitution écrite"},{"id":"i5","texte":"La souveraineté nationale"}]},{"enonce":"Que montre l’ensemble de ces documents ?","aide":"Compare les principes affichés et ce que dit la lettre.","type":"choix","options":[{"id":"a","texte":"Le peuple souverain est proclamé, mais la citoyenneté reste limitée"},{"id":"b","texte":"Le suffrage universel est réalisé dès 1789 dans tous les pays"},{"id":"c","texte":"Toutes les révolutions abolissent l’esclavage dans leur pays"},{"id":"d","texte":"Le modèle représentatif est abandonné au profit du vote direct"}],"multiple":false}]}$ex$::jsonb,
