  ('308e0606-d47f-55d7-8fc0-ac9ac7701666'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le voyageur français sur les routes d’Amérique","competence":"analyser-texte","situation":"En 1831, un jeune Français parcourt les États-Unis pour comprendre l’avenir des sociétés égalitaires. Un récit écrit pour l’exercice résume ce qu’il observe.","documents":[{"id":"voyage","type":"texte","genre":"recit","titre":"Ce que le voyageur observe, 1831","source":"Texte écrit pour l’exercice, d’après les observations de Tocqueville dans De la démocratie en Amérique.","blocs":["En 1831, un jeune Français, Alexis de Tocqueville, parcourt les États-Unis. Il veut comprendre l’avenir des sociétés où les conditions deviennent égales, un mouvement qu’il juge irrésistible.","Partout, il voit des habitants qui s’unissent en associations pour ouvrir une école, bâtir une route ou défendre une cause.","Il remarque aussi que chaque commune gère elle-même ses affaires, que la justice est indépendante et que la religion est séparée de l’État."]}],"questions":[{"enonce":"Touche le mot qui désigne les groupes où les Américains apprennent à agir ensemble.","aide":"Ils s’unissent pour ouvrir une école ou bâtir une route.","type":"zone","document":"voyage","multiple":false},{"enonce":"Touche le mot par lequel Tocqueville juge l’égalisation des conditions.","aide":"Il pense qu’on ne peut pas l’arrêter.","type":"zone","document":"voyage","multiple":false},{"enonce":"Associe chaque institution américaine à ce qu’elle apporte, selon Tocqueville.","aide":"Relis le deuxième et le troisième paragraphe.","type":"association","gauche":[{"id":"g0","texte":"Les associations"},{"id":"g1","texte":"L’administration locale"},{"id":"g2","texte":"La religion séparée de l’État"}],"droite":[{"id":"d0","texte":"Elle soutient les mœurs sans les contraindre"},{"id":"d1","texte":"Elles forment à l’action collective"},{"id":"d2","texte":"Elle est une école pratique de la liberté"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m38"]},"explication":"Ce sont les **associations** : elles forment à l’action collective et font contrepoids à l’État."},{"cle":{"type":"zone","ids":["m28"]},"explication":"Pour lui, l’égalisation des conditions est **irrésistible** : il n’y cherche pas un modèle mais un avenir."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Les **associations** apprennent à agir ensemble, la **commune** est une école de la liberté, la **religion**, séparée de l’État, soutient les mœurs au lieu de les contraindre."}]$ex$::jsonb),
  ('308e0606-d47f-55d7-8fc0-ac9ac7701666'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Trois villes, trois dangers","competence":"analyser-texte","situation":"Trois petites villes imaginées illustrent les trois périls que Tocqueville voit dans les démocraties. À toi de les reconnaître.","documents":[{"id":"villes","type":"texte","genre":"article","titre":"Trois scènes d’une société d’égaux","source":"Texte écrit pour l’exercice, d’après les trois périls décrits par Tocqueville.","blocs":["Dans la petite ville de Dunmore, quand l’opinion du plus grand nombre est fixée, personne n’ose plus la contredire : l’élève qui pense autrement préfère se taire.","À Brookvale, chacun rentre chez soi le soir, s’occupe de sa famille et de ses amis, et ne se soucie plus des affaires de la cité.","À Orlington, un pouvoir immense prend en charge le logement, les loisirs et l’avenir de chacun. Les habitants lui sont reconnaissants et ne décident plus rien par eux-mêmes."]}],"questions":[{"enonce":"Associe chaque paragraphe au péril qu’il illustre.","aide":"Pour chaque scène, demande-toi qui exerce la pression : l’opinion, le repli sur soi ou un pouvoir.","type":"association","gauche":[{"id":"g0","texte":"Paragraphe 1"},{"id":"g1","texte":"Paragraphe 2"},{"id":"g2","texte":"Paragraphe 3"}],"droite":[{"id":"d0","texte":"Despotisme doux"},{"id":"d1","texte":"Tyrannie de la majorité"},{"id":"d2","texte":"Individualisme"}]},{"enonce":"Touche le mot qui montre que les habitants d’Orlington consentent à ce pouvoir.","aide":"Que ressentent-ils envers ce pouvoir ?","type":"zone","document":"villes","multiple":false},{"enonce":"Comment le pouvoir d’Orlington traite-t-il les citoyens ?","aide":"Ce pouvoir ne tyrannise pas : il prend tout en charge.","type":"choix","options":[{"id":"a","texte":"Il laisse les citoyens décider seuls de toutes leurs affaires"},{"id":"b","texte":"Il impose sa volonté par la terreur et les arrestations arbitraires"},{"id":"c","texte":"Il est renversé par les habitants qui refusent de lui obéir"},{"id":"d","texte":"Il infantilise les citoyens, qui y consentent parce qu’il les soulage"}],"multiple":false},{"enonce":"Parmi ces institutions, laquelle Tocqueville présente-t-il comme un remède à l’individualisme ?","aide":"Elle apprend aux citoyens à agir ensemble.","type":"choix","options":[{"id":"a","texte":"Les associations"},{"id":"b","texte":"La censure de la presse"},{"id":"c","texte":"La centralisation de l’administration"},{"id":"d","texte":"Un État qui s’occupe de tout"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"Dunmore : la pression morale de l’opinion, **tyrannie de la majorité**. Brookvale : le retrait du public, **individualisme**. Orlington : un pouvoir tutélaire qui infantilise, **despotisme doux**."},{"cle":{"type":"zone","ids":["m77"]},"explication":"Ils lui sont **reconnaissants** : le despotisme doux n’est pas imposé, il est accepté parce qu’il soulage."},{"cle":{"type":"choix","ids":["d"]},"explication":"C’est un pouvoir **tutélaire** : il prend tout en charge et ôte aux citoyens l’usage d’eux-mêmes, sans violence."},{"cle":{"type":"choix","ids":["a"]},"explication":"Les **associations** font sortir du cercle privé et forment à l’action collective : c’est l’un des remèdes de Tocqueville, avec la presse libre et la décentralisation."}]$ex$::jsonb),
  ('308e0606-d47f-55d7-8fc0-ac9ac7701666'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Valmont, la ville où l’application décide de tout","competence":"argumenter","situation":"À Valmont, ville imaginée, une application municipale s’occupe de presque tout. Que dirait Tocqueville d’un tel pouvoir et de la participation des habitants ?","documents":[{"id":"valmont","type":"texte","genre":"article","titre":"Une ville connectée","source":"Texte écrit pour l’exercice. Ville imaginée.","blocs":["À Valmont, l’application Cité+ réserve les places de cantine, attribue les places de crèche, trie les propositions des habitants et rédige elle-même les réponses de la mairie.","Les habitants en sont satisfaits : « Tout est réglé, on n’a plus à s’en occuper », disent-ils. Au dernier conseil de quartier, douze personnes étaient présentes."]},{"id":"participation","type":"graphique","forme":"barres","titre":"Participation aux municipales de Valmont","source":"Chiffres imaginés pour l’exercice.","categories":["2008","2014","2020"],"series":[{"nom":"Participation","valeurs":[58,49,38],"teinte":"violet"}],"axeY":{"titre":"Participation","unite":"% des inscrits","min":0,"max":80,"pas":20},"valeurs":false}],"questions":[{"enonce":"De combien de points la participation a-t-elle baissé entre 2008 et 2020 ?","aide":"Lis la première et la dernière barre, puis soustrais.","type":"nombre","unite":"points"},{"enonce":"Touche l’élection où la participation est la plus faible.","aide":"Cherche la barre la plus basse.","type":"zone","document":"participation","multiple":false},{"enonce":"L’application qui prend tout en charge à Valmont se rapproche de quel péril ?","aide":"Les habitants sont satisfaits et ne décident plus rien.","type":"choix","options":[{"id":"a","texte":"L’individualisme : chacun ne s’occupe que de sa propre vie privée"},{"id":"b","texte":"La démocratie directe : les habitants votent chaque décision"},{"id":"c","texte":"Le despotisme doux : un pouvoir qui prend tout en charge et qu’on accepte"},{"id":"d","texte":"La tyrannie de la majorité : l’opinion dominante écrase la minorité"}],"multiple":false},{"enonce":"Range chaque élément : remède de Tocqueville ou péril ?","aide":"Les remèdes redonnent du pouvoir aux citoyens, les périls leur en ôtent.","type":"categories","categories":[{"id":"c0","texte":"Un remède"},{"id":"c1","texte":"Un péril"}],"items":[{"id":"i0","texte":"Des habitants qui ne votent plus parce que tout est réglé"},{"id":"i1","texte":"Une association d’habitants qui gère la fête du quartier"},{"id":"i2","texte":"Un conseil de quartier qui vote lui-même son budget"},{"id":"i3","texte":"Une application qui décide à la place des habitants"},{"id":"i4","texte":"Une presse locale libre qui enquête sur la mairie"}]},{"enonce":"Que pourrait proposer Tocqueville pour redonner aux habitants le goût des affaires communes ?","aide":"Pour lui, la liberté demande des institutions et des mœurs.","type":"choix","options":[{"id":"a","texte":"Supprimer l’élection du conseil municipal pour gagner du temps"},{"id":"b","texte":"Interdire les associations pour éviter les désaccords locaux"},{"id":"c","texte":"Laisser l’application décider de toutes les questions importantes"},{"id":"d","texte":"Rendre des décisions aux habitants, par leurs associations et leur commune"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 points","explication":"58 − 38 = **20 points** de moins en douze ans."},{"cle":{"type":"zone","ids":["k2"]},"explication":"L’élection de **2020** : 38 % seulement des inscrits ont voté."},{"cle":{"type":"choix","ids":["c"]},"explication":"Cité+ est un pouvoir **tutélaire** qui soulage les habitants et les dispense de décider : c’est le **despotisme doux**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c0"}},"explication":"**Remèdes** : associations, décentralisation (conseil de quartier), presse libre. **Périls** : le pouvoir qui décide à la place des habitants et le retrait du public."},{"cle":{"type":"choix","ids":["d"]},"explication":"La liberté ne se conserve pas d’elle-même : elle demande des **institutions** (communes, associations, presse libre) qui font participer les citoyens."}]$ex$::jsonb),
