s fondamentales"},{"id":"d1","texte":"La séparation des pouvoirs"},{"id":"d2","texte":"Le pluralisme"}]},{"enonce":"Combien d’années séparent le coup d’État du référendum de 1988 ?","aide":"Soustrais 1973 à 1988.","type":"nombre","unite":"ans"},{"enonce":"Que montre le cas chilien ?","aide":"Le Chili était l’une des démocraties les plus stables d’Amérique latine.","type":"choix","options":[{"id":"a","texte":"Une démocratie est protégée de tout risque par sa Constitution"},{"id":"b","texte":"Une démocratie solide peut s’effondrer en quelques années de crise"},{"id":"c","texte":"Une démocratie ne tombe jamais quand elle a plus de cinquante ans"},{"id":"d","texte":"Une démocratie ne peut être renversée que par une invasion étrangère"}],"multiple":false}]}$ex$::jsonb,
