  ('aef00199-1d6e-522f-940d-71ad3a04d772'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Deux dictatures, deux sorties","competence":"analyser-document","situation":"Hugo compare la fin des deux dictatures de la péninsule ibérique. Un tableau lui donne les repères, puis il doit classer les faits.","documents":[{"id":"compare","type":"tableau","titre":"Portugal et Espagne","source":"D’après le cours.","colonnes":["","Portugal","Espagne"],"lignes":[["Nom du régime","Estado Novo","Franquisme"],["Début","1933","1939"],["Fin","1974","1975"],["Événement qui ouvre la sortie","Un mouvement d’officiers, le 25 avril","La mort de Franco, le 20 novembre"]],"enteteLignes":true}],"questions":[{"enonce":"De combien d’années la dictature portugaise a-t-elle duré plus longtemps que la dictature espagnole ?","aide":"Calcule la durée de chaque régime, puis fais la différence.","type":"nombre","unite":"ans"},{"enonce":"Touche la case qui dit ce qui ouvre la sortie de la dictature en Espagne.","aide":"Prends la dernière ligne, colonne de l’Espagne.","type":"zone","document":"compare","multiple":false},{"enonce":"Range chaque fait : rupture portugaise ou transition négociée espagnole ?","aide":"La rupture est révolutionnaire, la transition se négocie entre anciens et nouveaux acteurs.","type":"categories","categories":[{"id":"c0","texte":"Rupture (Portugal)"},{"id":"c1","texte":"Transition négociée (Espagne)"}],"items":[{"id":"i0","texte":"Un mouvement d’officiers renverse le régime"},{"id":"i1","texte":"Les pactes de la Moncloa"},{"id":"i2","texte":"Les Cortès franquistes votent leur propre disparition"},{"id":"i3","texte":"Décolonisation rapide et nationalisations"},{"id":"i4","texte":"Le roi désigné par Franco ouvre le régime"},{"id":"i5","texte":"Des œillets sont glissés dans les canons"}]},{"enonce":"Pourquoi la loi d’amnistie espagnole de 1977 est-elle encore discutée ?","aide":"Une amnistie efface les poursuites contre les responsables d’actes passés.","type":"choix","options":[{"id":"a","texte":"Elle a rétabli les pouvoirs absolus du roi dans tout le pays"},{"id":"b","texte":"Elle a laissé sans réponse la question des crimes du franquisme"},{"id":"c","texte":"Elle a interdit le parti communiste pendant plusieurs années encore"},{"id":"d","texte":"Elle a empêché l’adoption de la Constitution de 1978 par référendum"}],"multiple":false}]}$ex$::jsonb,
