  ('aef00199-1d6e-522f-940d-71ad3a04d772'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Lisbonne 1974, Madrid 1981","competence":"analyser-document","situation":"Deux matins marquent la naissance des démocraties ibériques. Une carte situe les capitales et une chronique imaginée raconte les deux journées.","documents":[{"id":"carte","type":"carte","titre":"La péninsule ibérique","source":"Carte schématique.","fond":"mediterranee","cadrage":[-11,35,5,45],"frontieres":true,"lieux":[{"id":"z1","lieu":"lisbonne","symbole":"lettre","lettre":"A"},{"id":"z2","lieu":"madrid","symbole":"lettre","lettre":"B"}]},{"id":"chronique","type":"texte","genre":"article","titre":"Deux matins dans la péninsule ibérique","source":"Chronique écrite pour l’exercice.","blocs":["25 avril 1974. À Lisbonne, des officiers prennent la radio et marchent sur la capitale. La foule envahit les rues et glisse des œillets dans les canons des fusils. Le régime tombe presque sans effusion de sang.","23 février 1981. À Madrid, des militaires armés font irruption dans le Parlement. Dans la nuit, le roi Juan Carlos s’adresse à la télévision et refuse le coup d’État : il échoue."]}],"questions":[{"enonce":"Touche la capitale où des officiers ont renversé la dictature en 1974.","aide":"Elle est sur la côte atlantique, à l’ouest de la péninsule.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche le mot qui désigne les fleurs glissées dans les canons.","aide":"Elles ont donné son nom à la révolution.","type":"zone","document":"chronique","multiple":false},{"enonce":"Touche la capitale où des militaires ont investi le Parlement en 1981.","aide":"Elle est au centre de la péninsule.","type":"zone","document":"carte","multiple":false},{"enonce":"Que montre l’attitude du roi Juan Carlos en 1981 ?","aide":"Il avait été désigné par Franco, mais il a ouvert le régime.","type":"choix","options":[{"id":"a","texte":"Que le roi choisit de défendre la démocratie qu’il a contribué à ouvrir"},{"id":"b","texte":"Que l’armée espagnole est unanimement favorable au putsch"},{"id":