  ('cbd77eac-7f69-57a6-b9e4-534fcd11ef58'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Inès et Malo débattent de l’Europe","competence":"argumenter","situation":"Deux lycéens se disputent par messages : l’Union européenne est-elle démocratique ? Un graphique sur la participation aux européennes vient nourrir leur débat.","documents":[{"id":"sms","type":"dialogue","modele":"sms","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Malo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"L’Union n’est pas démocratique : la Commission n’est pas élue et c’est elle qui propose les lois."},{"qui":"Malo","texte":"Mais le Parlement est élu depuis 1979, il vote le budget et il peut la censurer. Et les ministres de nos gouvernements siègent au Conseil."},{"qui":"Inès","texte":"Peut-être, mais la moitié de mes amis ne vote pas aux européennes, et personne ne sait vraiment qui décide quoi."}]},{"id":"participation","type":"graphique","forme":"barres","titre":"Participation aux élections européennes","source":"Chiffres arrondis, moyenne dans l’ensemble de l’Union.","categories":["1979","1999","2014","2019"],"series":[{"nom":"Participation","valeurs":[62,50,43,51],"teinte":"violet"}],"axeY":{"titre":"Participation","unite":"%","min":0,"max":80,"pas":20},"valeurs":false}],"questions":[{"enonce":"Touche le mot qui désigne l’institution non élue qui propose les lois.","aide":"Inès la cite dans son premier message.","type":"zone","document":"sms","multiple":false},{"enonce":"Touche l’année où la participation a été la plus faible.","aide":"Cherche la barre la plus basse.","type":"zone","document":"participation","multiple":false},{"enonce":"De combien de points la participation a-t-elle baissé entre 1979 et 2014 ?","aide":"Lis la première barre et la barre de 2014, puis soustrais.","type":"nombre","unite":"points"},{"enonce":"Les chiffres du graphique donnent-ils raison à Inès sur l’abstention ?","aide":"Compare 1979, 2014 et 2019.","type":"choix","options":[{"id":"a","texte":"Non : la participation a toujours dépassé les 60 % des inscrits"},{"id":"b","texte":"Non : la participation a augmenté à chaque élection depuis 1979"},{"id":"c","texte":"Oui, en partie : plus basse en 2014 qu’en 1979, elle remonte en 2019"},{"id":"d","texte":"Oui : la participation est tombée sous les 20 % en 2014"}],"multiple":false},{"enonce":"Complète le cœur du débat.","aide":"Les nations aussi se sont construites peu à peu.","type":"trous","segments":["Certains pensent qu’il manque à l’Union un ",0,", un peuple qui se reconnaisse comme tel ; d’autres y voient un processus ",1,", comme le furent les nations."],"banque":["achevé","en cours","demos","impossible"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m7"]},"explication":"La **Commission** a le monopole de l’initiative des textes, d’où le reproche de technocratie."},{"cle":{"type":"zone","ids":["k2"]},"explication":"En **2014**, la participation est la plus basse du graphique : 43 %."},{"cle":{"type":"nombre","valeur":19,"tolerance":0},"affichage":"19 points","explication":"62 − 43 = **19 points** de moins."},{"cle":{"type":"choix","ids":["c"]},"explication":"La participation recule de 62 % à 43 % entre 1979 et 2014, puis **remonte** à 51 % en 2019 : Inès a raison pour la tendance, pas pour toute la période."},{"cle":{"type":"trous","trous":[["demos","peuple"],["en cours"]]},"affichage":"demos · en cours","explication":"La question est celle d’une démocratie sans **demos**. Pour certains, c’est un obstacle ; pour d’autres, un processus **en cours**, comme les nations."}]$ex$::jsonb),
