   $ex${"titre":"Deux empires en déclin, deux réponses","competence":"argumenter","situation":"Une frise place côte à côte l’Empire ottoman et la Russie post-soviétique. Une note de lecture imaginée invite à penser le déclin comme un processus.","documents":[{"id":"frise","type":"frise","titre":"Deux trajectoires, 1880-2025","source":"D’après le cours.","debut":1880,"fin":2025,"pas":20,"evenements":[{"id":"z1","date":1881,"nom":"Dette ottomane"},{"id":"z2","date":1908,"nom":"Jeunes-Turcs"},{"id":"z3","date":1923,"nom":"République turque"},{"id":"z4","date":1991,"nom":"Fin de l’URSS"},{"id":"z5","date":2008,"nom":"Géorgie"},{"id":"z6","date":2014,"nom":"Crimée"},{"id":"z7","date":2022,"nom":"Invasion Ukraine"}]},{"id":"note","type":"texte","genre":"article","titre":"Note de lecture","source":"Texte écrit pour l’exercice.","blocs":["Un déclin n’est presque jamais un effondrement soudain. Il se prépare par des retards accumulés, des dépendances financières, des contestations internes et des recompositions du commerce mondial.","Et la réponse qu’une puissance y apporte compte autant que les causes."]}],"questions":[{"enonce":"Touche l’événement par lequel des réformateurs tentent de relever l’Empire ottoman en 1908.","aide":"C’est une révolution, en 1908.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent l’Administration de la Dette publique ottomane de la République turque ?","aide":"Soustrais 1881 à 1923.","type":"nombre","unite":"ans"},{"enonce":"Range chaque fait : trajectoire ottomane ou russe post-URSS ?","aide":"L’un s’est réformé en s’européanisant, l’autre s’est réaffirmé par la force.","type":"categories","categories":[{"id":"c0","texte":"Empire ottoman"},{"id":"c1","texte":"Russie post-URSS"}],"items":[{"id":"i0","texte":"Les Tanzimat"},{"id":"i1","texte":"La rente énergétique comme instrument diplomatique"},{"id":"i2","texte":"La guerre en Géorgie en 2008"},{"id":"i3","texte":"L’annexion de la Crimée"},{"id":"i4","texte":"L’Administration de la Dette publique"},{"id":"i5","texte":"Les capitulations"}]},{"enonce":"Touche le mot qui dit ce qui s’accumule avant un déclin.","aide":"Ce sont des choses en avance ou en retard sur les autres.","type":"zone","document":"note","multiple":false},{"enonce":"Selon la note de lecture, comment arrive un déclin ?","aide":"Relis la première phrase de la note.","type":"choix","options":[{"id":"a","texte":"Il vient toujours d’une crise économique soudaine et imprévisible"},{"id":"b","texte":"Il ne dépend jamais des choix faits par la puissance elle-même"},{"id":"c","texte":"Il survient toujours après une seule défaite militaire brutale et soudaine"},{"id":"d","texte":"Il se prépare lentement : retards, dépendances financières et contestations"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"La **révolution des Jeunes-Turcs** (1908) tente de réformer l’empire, mais elle ne renverse pas le mouvement de déclin."},{"cle":{"type":"nombre","valeur":42,"tolerance":0},"affichage":"42 ans","explication":"1923 − 1881 = **42 ans**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c1","i4":"c0","i5":"c0"}},"explication":"**Ottoman** : Tanzimat, Dette publique, capitulations. **Russie** : énergie, Crimée, Géorgie."},{"cle":{"type":"zone","ids":["m14"]},"explication":"Ce sont des **retards** accumulés, notamment techniques et industriels, qui préparent le déclin."},{"cle":{"type":"choix","ids":["d"]},"explication":"Le déclin est un **processus long**, fait de retards, de dépendances et de contestations. La réponse de la puissance pèse autant que les causes."}]$ex$::jsonb),
