   $ex${"titre":"Un pétrolier entre Ormuz et Malacca","competence":"lire-carte","situation":"Mehdi, officier de marine, doit conduire un pétrolier du golfe Persique jusqu’à un port d’Asie. Avant d’embarquer, il relit sur la carte les passages obligés de la route.","documents":[{"id":"carte","type":"carte","titre":"Quatre passages stratégiques","source":"Carte schématique, d’après le cours.","fond":"monde","cadrage":[-10,-10,125,48],"lieux":[{"id":"z1","lon":32.5,"lat":30,"symbole":"lettre","lettre":"A"},{"id":"z2","lon":43.4,"lat":12.6,"symbole":"lettre","lettre":"B"},{"id":"z3","lon":56.3,"lat":26.5,"symbole":"lettre","lettre":"C"},{"id":"z4","lon":101.2,"lat":2.8,"symbole":"lettre","lettre":"D"}]}],"questions":[{"enonce":"Touche le détroit d’Ormuz, par où sort le pétrole du Golfe.","aide":"Il ferme le golfe Persique, au sud de l’Iran.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche le détroit de Malacca, qui commande le commerce asiatique.","aide":"Il passe entre la péninsule malaise et l’île de Sumatra, près de Singapour.","type":"zone","document":"carte","multiple":false},{"enonce":"Relie chaque passage à ce qu’il commande.","aide":"Relis le tableau « Les voies de communication » : un passage, une fonction.","type":"association","gauche":[{"id":"g0","texte":"Ormuz"},{"id":"g1","texte":"Malacca"},{"id":"g2","texte":"Canal de Suez"},{"id":"g3","texte":"Câbles sous-marins"}],"droite":[{"id":"d0","texte":"L’essentiel des données mondiales"},{"id":"d1","texte":"Le commerce asiatique"},{"id":"d2","texte":"Le pétrole du Golfe"},{"id":"d3","texte":"Un blocage désorganise le commerce mondial"}]}]}$ex$::jsonb,
