  ('72f69dbc-afe6-5f92-acef-dea0913e18f8'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les séries d’un petit pays","competence":"analyser-texte","situation":"Dans la classe d’Inès, tout le monde parle d’un pays de taille moyenne devenu une référence mondiale. Inès note ce que cela change autour d’elle.","documents":[{"id":"carnet","type":"texte","genre":"article","titre":"Le carnet d’Inès","source":"Texte écrit pour l’exercice.","blocs":["Dans la classe d’Inès, on écoute la musique et on regarde les séries d’un pays de taille moyenne devenu une référence mondiale.","Plusieurs élèves se mettent à apprendre sa langue, puis rêvent d’aller y étudier.","Son grand frère, parti une année dans une université de ce pays, en est revenu avec des amis, des contacts et une vraie familiarité avec la culture locale."]}],"questions":[{"enonce":"Touche les deux produits culturels qui font connaître ce pays dans le monde.","aide":"Cherche ce qu’on écoute et ce qu’on regarde.","type":"zone","document":"carnet","multiple":true},{"enonce":"Touche les trois choses que le grand frère a rapportées de son année d’études.","aide":"Il s’agit de liens et d’habitudes durables, pas d’objets.","type":"zone","document":"carnet","multiple":true},{"enonce":"À quelle forme de puissance renvoie cette histoire ?","aide":"Aucun soldat, aucune sanction : on regarde, on écoute, on apprend.","type":"choix","options":[{"id":"a","texte":"Une puissance financière, qui sanctionne les rivaux"},{"id":"b","texte":"Une puissance militaire, qui impose sa volonté"},{"id":"c","texte":"Une puissance indirecte, qui attire sans contraindre"},{"id":"d","texte":"Une puissance territoriale, qui annexe des espaces"}],"multiple":false},{"enonce":"Classe chaque exemple selon le vecteur de puissance qu’il illustre.","aide":"Une technologie critique est une ressource ou un produit dont la concentration donne prise.","type":"categories","categories":[{"id":"c0","texte":"Culture"},{"id":"c1","texte":"Langue"},{"id":"c2","texte":"Technologie critique"}],"items":[{"id":"i0","texte":"L’anglais, langue de la publication scientifique"},{"id":"i1","texte":"Les terres rares"},{"id":"i2","texte":"Les jeux vidéo"},{"id":"i3","texte":"Les séries coréennes"},{"id":"i4","texte":"Les semi-conducteurs"},{"id":"i5","texte":"Les instituts Confucius"}]}]}$ex$::jsonb,
