 deux documents ?","aide":"Compte les flèches du schéma avant de conclure.","type":"choix","options":[{"id":"a","texte":"Une dépendance à sens unique en faveur de la zone A"},{"id":"b","texte":"Une indépendance complète de la zone B"},{"id":"c","texte":"Une puissance qui ne repose que sur la force armée"},{"id":"d","texte":"Une dépendance mutuelle : chacune tient l’autre"}],"multiple":false}]}$ex$::jsonb,
