  ('d31479de-cabb-57ee-a6f3-12cce3df08dc'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Plus qu’une puissance, moins qu’en 1991","competence":"analyser-document","situation":"Un analyste imaginaire résume la position des États-Unis. Zoé doit croiser sa note avec une frise pour séparer le vrai du trop simple.","documents":[{"id":"frise","type":"frise","titre":"Les repères de la puissance américaine","debut":1940,"fin":2010,"pas":10,"evenements":[{"id":"z1","date":1945,"nom":"Ordre de 1945"},{"id":"z2","date":1991,"nom":"Fin de l’URSS"},{"id":"z3","date":2001,"nom":"Afghanistan"},{"id":"z4","date":2003,"nom":"Irak"}]},{"id":"note","type":"texte","genre":"article","titre":"La note de l’analyste","source":"Texte écrit pour l’exercice.","blocs":["Les États-Unis ont été l’architecte de l’ordre international né en 1945, mais ils s’en écartent parfois quand leurs intérêts l’exigent.","Leur puissance est relativement moins dominante qu’en 1991, mais aucune autre ne réunit autant d’atouts : armée, dollar, culture, recherche.","Chez eux, les guerres d’Irak et d’Afghanistan ont nourri un débat sur l’engagement extérieur, et la polarisation rend leur diplomatie moins prévisible."]}],"questions":[{"enonce":"Touche le mot qui dit que le recul américain n’est pas total.","aide":"C’est un adverbe, dans le deuxième paragraphe.","type":"zone","document":"note","multiple":false},{"enonce":"Touche l’événement qui sert de point de comparaison pour parler d’une puissance « moins dominante ».","aide":"La note cite une année précise dans le deuxième paragraphe.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la fin de l’URSS de l’entrée en guerre en Irak ?","aide":"Soustrais les deux dates de la frise.","type":"nombre","unite":"ans"},{"enonce":"Complète la conclusion du cours.","aide":"Le premier mot est dans la note, le second qualifie une puissance présente partout.","type":"trous","segments":["La puissance américaine est ",0," moins dominante qu’en 1991, mais elle reste la seule puissance ",1,"."],"banque":["totalement","relativement","égale","complète"]},{"enonce":"Que signifie « multipolarité » pour les États-Unis aujourd’hui ?","aide":"Les pôles existent, mais la note dit qu’un seul réunit tous les atouts.","type":"choix","options":[{"id":"a","texte":"Un seul pôle de puissance, sans aucun rival"},{"id":"b","texte":"La disparition de toute puissance américaine"},{"id":"c","texte":"Plusieurs pôles de puissance strictement égaux"},{"id":"d","texte":"Plusieurs pôles de puissance, mais inégaux"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m27"]},"explication":"Le mot **« relativement »** nuance : leur puissance recule face aux autres, mais ne s’effondre pas."},{"cle":{"type":"zone","ids":["z2"]},"explication":"On compare à **1991**, la fin de l’URSS, quand les États-Unis dominaient sans rival."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12 ans","explication":"2003 − 1991 = **12 ans**."},{"cle":{"type":"trous","trous":[["relativement"],["complete"]]},"affichage":"relativement · complète","explication":"**Relativement** moins dominante, mais seule puissance **complète** : présente sur tous les registres à la fois."},{"cle":{"type":"choix","ids":["d"]},"explication":"Multipolarité ne signifie pas égalité des pôles : les États-Unis restent seuls à réunir **tous** les attributs."}]$ex$::jsonb),
  ('3481d305-9ba4-5ea3-af54-f5dfc7910c17'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un îlot, deux cents milles","competence":"observer-schema","situation":"Karim, géographe, étudie un îlot inhabité de quelques rochers. Pourtant plusieurs États se le disputent. Un schéma de la mer autour de l’îlot lui explique pourquoi.","documents":[{"id":"ilot","type":"schema","titre":"La mer autour d’un îlot, vue de dessus","source":"Schéma non proportionnel, d’après la convention de Montego Bay.","largeur":320,"hauteur":240,"elements":[{"forme":"cercle","cx":160,"cy":120,"r":100,"teinte":"bleu","motif":"clair","id":"z1","zone":true},{"forme":"cercle","cx":160,"cy":120,"r":42,"teinte":"ciel","motif":"plein","id":"z2","zone":true},{"forme":"cercle","cx":160,"cy":120,"r":7,"teinte":"sable","motif":"plein","id":"z3","zone":true},{"forme":"etiquette","x":270,"y":22,"texte":"200 milles","vers":[231,49]},{"forme":"etiquette","x":52,"y":222,"texte":"12 milles","vers":[130,150]}]}],"questions":[{"enonce":"Touche la mer territoriale, où l’État est souverain comme sur sa terre.","aide":"C’est la zone la plus proche de l’îlot, limitée à 12 milles.","type":"zone","document":"ilot","multiple":false},{"enonce":"Touche la zone économique exclusive, en dehors de la mer territoriale.","aide":"C’est la grande zone, jusqu’à 200 milles.","type":"zone","document":"ilot","multiple":false},{"enonce":"Sur quel rayon, en milles marins, l’îlot ouvre-t-il des droits sur les ressources ?","aide":"Lis la plus grande distance écrite sur le schéma.","type":"nombre","unite":"milles"},{"enonce":"Pourquoi des États se disputent-ils un îlot aussi modeste ?","aide":"Pense à ce qui se trouve autour de l’îlot, pas dessus.","type":"choix","options":[{"id":"a","texte":"Il ouvre des droits sur une vaste zone de ressources"},{"id":"b","texte":"Il permet d’y bâtir de grandes villes portuaires"},{"id":"c","texte":"Il porte une frontière naturelle indiscutable"},{"id":"d","texte":"Il offre des terres agricoles très fertiles"}],"multiple":false}]}$ex$::jsonb,
