  ('3481d305-9ba4-5ea3-af54-f5dfc7910c17'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le fleuve qui devint frontière","competence":"analyser-texte","situation":"Léna lit le récit imaginaire d’un fleuve qui sépare désormais deux États. Elle se demande si une frontière peut vraiment être « naturelle ».","documents":[{"id":"fleuve","type":"texte","genre":"article","titre":"Le fleuve de Valmar","source":"Texte écrit pour l’exercice.","blocs":["Pendant des siècles, le fleuve a porté les barques, les marchands et les mariages d’une rive à l’autre. Les deux villages partagent un marché et une langue.","Au XIXe siècle, pourtant, un traité signé loin de là en fait la limite entre deux États. On dira désormais que le fleuve est une frontière « naturelle »."]}],"questions":[{"enonce":"Touche les deux éléments qui montrent que le fleuve unit les deux rives.","aide":"Cherche ce que les deux villages ont en commun.","type":"zone","document":"fleuve","multiple":true},{"enonce":"Qui a décidé que ce fleuve serait une frontière ?","aide":"Relis la première phrase du deuxième paragraphe.","type":"choix","options":[{"id":"a","texte":"La nature, qui sépare toujours les rives"},{"id":"b","texte":"Les villageois, par un vote immémorial"},{"id":"c","texte":"Le fleuve lui-même, par sa largeur"},{"id":"d","texte":"Un traité, donc une décision politique"}],"multiple":false},{"enonce":"Classe chaque tracé : naturel ou géométrique ?","aide":"Un tracé géométrique se reconnaît à ses lignes droites, fréquentes en Afrique.","type":"categories","categories":[{"id":"c0","texte":"Naturel"},{"id":"c1","texte":"Géométrique"}],"items":[{"id":"i0","texte":"Un partage colonial en lignes droites"},{"id":"i1","texte":"Une ligne droite tracée à la règle"},{"id":"i2","texte":"Un fleuve"},{"id":"i3","texte":"Une crête montagneuse"},{"id":"i4","texte":"Un littoral"}]},{"enonce":"Relie chaque domaine à ce qui fixe sa frontière.","aide":"Relis le tableau « Les frontières autres que terrestres ».","type":"association","gauche":[{"id":"g0","texte":"Maritime"},{"id":"g1","texte":"Aérien"},{"id":"g2","texte":"Numérique"}],"droite":[{"id":"d0","texte":"La convention de Montego Bay (1982)"},{"id":"d1","texte":"Contrôle national d’Internet, filtrage"},{"id":"d2","texte":"Superposé à l’espace terrestre"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m25","m28"]},"explication":"Le **marché** et la **langue** sont partagés : le fleuve circulait, il n’avait rien de séparateur."},{"cle":{"type":"choix","ids":["d"]},"explication":"Une frontière est toujours une **construction politique** : ici, un traité."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c1","i2":"c0","i3":"c0","i4":"c0"}},"explication":"**Naturels** : fleuve, crête, littoral. **Géométriques** : tracés à la règle, souvent hérités de partages coloniaux."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**Maritime** : Montego Bay (1982) ; **aérien** : superposé au sol ; **numérique** : filtrage et contrôle national d’Internet."}]$ex$::jsonb),
  ('3481d305-9ba4-5ea3-af54-f5dfc7910c17'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Des frontières à géométrie variable","competence":"analyser-document","situation":"Noa compare ce qui franchit une frontière selon le passeport qu’on détient, puis un reportage imaginé sur une frontière floue. Il veut voir comment la mondialisation change les frontières.","documents":[{"id":"passeports","type":"tableau","titre":"Ce qui franchit la frontière","source":"Tableau simplifié écrit pour l’exercice.","colonnes":["Ce qui passe","Passeport A","Passeport B"],"lignes":[["Capitaux","Libres","Libres"],["Marchandises","Droits faibles","Droits faibles"],["Personnes","Entrée sans visa","Visa et contrôle approfondi"],["Données","Stockage dans le pays","Stockage dans le pays"]],"enteteLignes":true},{"id":"reportage","type":"texte","genre":"article","titre":"Aux confins","source":"Reportage imaginé pour l’exercice.","blocs":["À la frontière de ce pays imaginé, il n’y a pas de ligne nette : les bergers passent d’un côté à l’autre, et l’autorité de l’État s’estompe dans les collines.","Plus loin, dans la plaine, un mur de béton ferme chaque chemin."]}],"questions":[{"enonce":"Sur les quatre lignes du tableau, pour combien le passeport B est-il traité différemment du passeport A ?","aide":"Compare les deux colonnes ligne par ligne.","type":"nombre"},{"enonce":"Que montre ce tableau sur la mondialisation et les frontières ?","aide":"Regarde quelle catégorie est sélective et quelles sont libres.","type":"choix","options":[{"id":"a","texte":"Elle les rend identiques pour chaque passeport"},{"id":"b","texte":"Elle les a fermées pour les capitaux"},{"id":"c","texte":"Elle les différencie selon ce qui passe"},{"id":"d","texte":"Elle les a fait disparaître pour tous"}],"multiple":false},{"enonce":"Touche les mots qui montrent que cette frontière est une zone plutôt qu’une ligne.","aide":"Cherche où l’État perd de son emprise.","type":"zone","document":"reportage","multiple":true},{"enonce":"Range chaque description : ligne, zone ou mur ?","aide":"La ligne est le tracé, le mur le rend visible, la zone est un espace.","type":"categories","categories":[{"id":"c0","texte":"Ligne"},{"id":"c1","texte":"Zone"},{"id":"c2","texte":"Mur"}],"items":[{"id":"i0","texte":"Des marges où l’autorité s’estompe"},{"id":"i1","texte":"La matérialisation la plus brutale de la frontière"},{"id":"i2","texte":"Un espace de transition entre deux États"},{"id":"i3","texte":"Un tracé net, cartographié"},{"id":"i4","texte":"Une barrière de béton le long du tracé"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":1,"tolerance":0},"affichage":"1","explication":"Seule la ligne **Personnes** diffère : tout le reste est identique pour les deux passeports."},{"cle":{"type":"choix","ids":["c"]},"explication":"Ouverte aux capitaux et aux marchandises, **sélective pour les personnes** : la mondialisation différencie les frontières."},{"cle":{"type":"zone","ids":["m26","m30","m31"]},"explication":"Là où l’**autorité s’estompe**, la frontière est une zone de confins, pas un tracé net."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c2","i2":"c1","i3":"c0","i4":"c2"}},"explication":"**Ligne** : tracé net. **Zone** : marges et transition. **Mur** : matérialisation brutale. Les murs sont passés de moins d’une dizaine à plusieurs dizaines."}]$ex$::jsonb),
  ('f0431fa1-bb0a-5633-b3cd-60c7b6283216'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Quatre siècles de frontières en une frise","competence":"se-reperer-temps","situation":"Malik prépare un exposé sur le traçage des frontières. Il a dressé une frise des grands moments, de la naissance du système international moderne à l’indépendance d’un État par référendum.","documents":[{"id":"frise","type":"frise","titre":"Quatre moments du traçage des frontières","source":"D’après le cours.","debut":1600,"fin":2050,"pas":50,"evenements":[{"id":"z1","date":1648,"nom":"Westphalie"},{"id":"z2","date":1884,"nom":"Conf. de Berlin"},{"id":"z3","date":1964,"nom":"Uti possidetis"},{"id":"z4","date":2011,"nom":"Soudan du Sud"}]}],"questions":[{"enonce":"Touche la conférence qui partage l’Afrique entre puissances européennes, sans consulter les peuples.","aide":"C’est la date de la fin du XIXe siècle.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent les traités de Westphalie de l’ouverture de la conférence de Berlin ?","aide":"Soustrais les deux dates de la frise.","type":"nombre","unite":"ans"},{"enonce":"Relie chaque moment à ce qu’il pose.","aide":"Relis le tableau « Les grands moments du traçage ».","type":"association","gauche":[{"id":"g0","texte":"Traités de Westphalie (1648)"},{"id":"g1","texte":"Conférence de Berlin (1884-1885)"},{"id":"g2","texte":"Traités de 1919-1920"},{"id":"g3","texte":"Décolonisation (années 1960)"}],"droite":[{"id":"d0","texte":"Le partage de l’Afrique"},{"id":"d1","texte":"L’héritage des frontières coloniales"},{"id":"d2","texte":"La souveraineté territoriale exclusive"},{"id":"d3","texte":"Le droit des peuples à disposer d’eux-mêmes"}]}]}$ex$::jsonb,
