  ('f0431fa1-bb0a-5633-b3cd-60c7b6283216'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Garder ou refaire les frontières ?","competence":"argumenter","situation":"Pour un jeu de rôle, Lucie lit le débat imaginé de deux délégués fictifs qui doivent décider du sort des frontières héritées de la colonisation.","documents":[{"id":"debat","type":"texte","genre":"theatre","titre":"Un débat imaginé","source":"Texte écrit pour l’exercice : les deux personnages sont fictifs.","blocs":[{"didascalie":"Une salle de conférence, au moment des indépendances. Deux délégués s’opposent."},{"personnage":"Awa","replique":"Ces frontières ont été tracées à la règle, sans nous consulter. Il faut les refaire."},{"personnage":"Tomas","replique":"Si nous en rouvrons une, nous les rouvrons toutes : ce seront des guerres en chaîne. Gardons-les, pour rester stables."}]}],"questions":[{"enonce":"Touche les deux mots du délégué qui défend la stabilité.","aide":"Cherche ce qu’il craint et ce qu’il veut préserver.","type":"zone","document":"debat","multiple":true},{"enonce":"Quel principe Tomas défend-il ?","aide":"Il propose de garder ce qui existe déjà.","type":"choix","options":[{"id":"a","texte":"Les nouveaux États héritent des frontières coloniales"},{"id":"b","texte":"Les anciennes puissances fixent les nouveaux tracés"},{"id":"c","texte":"Les peuples votent pour changer chaque frontière"},{"id":"d","texte":"Les nouveaux États retracent toutes leurs frontières"}],"multiple":false},{"enonce":"Quel arbitrage ce débat illustre-t-il ?","aide":"Awa dénonce un tracé injuste ; Tomas veut éviter les guerres.","type":"choix","options":[{"id":"a","texte":"L’économie contre la culture des peuples"},{"id":"b","texte":"La monnaie contre la défense du territoire"},{"id":"c","texte":"La justice du tracé contre la stabilité"},{"id":"d","texte":"La stabilité contre la justice du tracé"}],"multiple":false},{"enonce":"Range chaque situation selon ce qui rend un tracé conflictuel.","aide":"Demande-toi ce qui est en jeu : de la richesse, des gens ou un symbole.","type":"categories","categories":[{"id":"c0","texte":"Ressources"},{"id":"c1","texte":"Population partagée"},{"id":"c2","texte":"Valeur symbolique"}],"items":[{"id":"i0","texte":"Une zone de pêche très poissonneuse"},{"id":"i1","texte":"Un gisement de pétrole sous la ligne"},{"id":"i2","texte":"Une minorité installée des deux côtés"},{"id":"i3","texte":"Un berceau national que chaque camp réclame"},{"id":"i4","texte":"Un lieu saint revendiqué par deux États"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m41","m45"]},"explication":"Tomas craint des guerres en **chaîne** et veut rester **stable** : c’est l’argument de l’*uti possidetis juris*."},{"cle":{"type":"choix","ids":["a"]},"explication":"C’est l’***uti possidetis juris*** : les nouveaux États conservent les frontières héritées de la colonisation."},{"cle":{"type":"choix","ids":["d"]},"explication":"Garder des frontières reconnues arbitraires, c’est choisir la **stabilité** contre la **justice** du tracé : c’est le choix assumé par l’Organisation de l’unité africaine en 1964."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c2","i4":"c2"}},"explication":"**Ressources** : pétrole, pêche. **Population partagée** : minorité des deux côtés. **Valeur symbolique** : lieu saint, berceau national."}]$ex$::jsonb),
